solution.solution.py:
class InvalidRecord(Exception):
    pass


def parse_record(line):
    fields = []
    for f in line.split(","):
        fields.append(f.strip())
    if len(fields) != 3:
        raise InvalidRecord(f"expected 3 fields, got {len(fields)}")
    name, age_text, email = fields
    if not name:
        raise InvalidRecord("missing name")
    try:
        age = int(age_text)
    except ValueError as e:
        raise InvalidRecord(f"age is not a number: {age_text}") from e
    if not 0 <= age <= 150:
        raise InvalidRecord(f"age out of range: {age}")
    user, at, domain = email.partition("@")
    if not user or not at or not domain or "@" in domain:
        raise InvalidRecord(f"invalid email: {email}")
    return (name, age, email)


def load_records(lines):
    records, errors = [], []
    for number, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            records.append(parse_record(line))
        except InvalidRecord as e:
            errors.append(f"line {number}: {e}")
    return records, errors

unitTests:
@test("good records")
def _():
    check_eq(parse_record("Ada,36,ada@example.org"), ("Ada", 36, "ada@example.org"))
    check_eq(parse_record("  Grace Hopper , 85 , grace@navy.mil "), ("Grace Hopper", 85, "grace@navy.mil"))

@test("each problem")
def _():
    def message(line):
        try:
            parse_record(line)
        except InvalidRecord as e:
            return str(e)
        return "no error"
    check_eq(message("Ada,36"), "expected 3 fields, got 2")
    check_eq(message(" ,36,a@b"), "missing name")
    check_eq(message("Ada,thirty,a@b"), "age is not a number: thirty")
    check_eq(message("Ada,200,a@b"), "age out of range: 200")
    check_eq(message("Ada,36,ada.example.org"), "invalid email: ada.example.org")
    check_eq(message("Ada,36,a@b@c"), "invalid email: a@b@c")
    check_eq(message("Ada,36,@b"), "invalid email: @b")

@test("the cause is kept")
def _():
    try:
        parse_record("Ada,x,a@b")
    except InvalidRecord as e:
        check(isinstance(e.__cause__, ValueError), "raise ... from the ValueError")

@test("loading many lines")
def _():
    lines = ["Ada,36,ada@example.org", "", "oops", "Linus,-1,l@x", "Grace,85,g@n"]
    records, errors = load_records(lines)
    check_eq(records, [("Ada", 36, "ada@example.org"), ("Grace", 85, "g@n")])
    check_eq(errors, ["line 3: expected 3 fields, got 1", "line 4: age out of range: -1"])

